{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Valbenazine, which contains the same dimethoxy-tetrahydroisoquinoline core and a basic amine as the query, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid with an N-methyl group, has an absolute oral bioavailability of 30% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary amine with extensive first-pass metabolism, showed 52.3% systemic bioavailability after oral administration in cirrhotic patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Sulpiride, a basic benzamide with a methoxy group and limited permeability, has an absolute bioavailability of about 34% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Encainide, a basic amide with aromatic methoxy and a piperidine, has a mean oral bioavailability of 30% in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Alfentanil, a basic piperidine amide, has a baseline oral bioavailability of 37% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Levosulpiride, a close analogue of sulpiride with a basic amine and benzamide, had 23.4% oral bioavailability in healthy Chinese volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Praziquantel, a cyclic amide, had 27.2% bioavailability in patients with hepatic cirrhosis, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental analogues (valbenazine, noscapine, verapamil, sulpiride, encainide, alfentanil, levosulpiride, praziquantel) show absolute oral bioavailability values of 23-52%, all above the 20% threshold. The query shares key dimethoxyphenyl/THIQ, basic amine, and amide features with these compounds. Rifampin co-treatment low-F verapamil records are not applicable to baseline conditions. Thus, F >= 20% is supported.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for the query molecule itself.",
    "First-pass metabolism and intestinal permeability of the query are not experimentally measured; the low neutral fraction may affect absorption.",
    "Rifampin co-treatment verapamil records are excluded because the query is not under enzyme induction.",
    "One alfentanil record reporting 1% is inconsistent with multiple other direct measurements and was not weighted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

